// src/core/world/routes/world.routes.ts
import { FastifyPluginAsync } from 'fastify';
import { worldService } from '../services/world.service';
import {
  getStatesByCountryParamsSchema,
  getCitiesByStateParamsSchema,
  searchCitiesQuerySchema,
} from '../world.schemas';

const worldRoutes: FastifyPluginAsync = async (fastify) => {
  /**
   * GET /world/countries
   * Lista todos os países
   */
  fastify.get('/countries', async () => {
    return worldService.getCountries();
  });

  /**
   * GET /world/countries/:countryId
   * Busca país por ID
   */
  fastify.get<{ Params: { countryId: string } }>(
    '/countries/:countryId',
    async (req, reply) => {
      const { countryId } = req.params;
      const country = await worldService.getCountryById(countryId);

      if (!country) {
        return reply.notFound('País não encontrado');
      }

      return country;
    }
  );

  /**
   * GET /world/countries/:countryId/states
   * Lista estados de um país
   */
  fastify.get<{ Params: { countryId: string } }>(
    '/countries/:countryId/states',
    async (req, reply) => {
      const { countryId } = req.params;
      
      // Validar countryId
      const country = await worldService.getCountryById(countryId);
      if (!country) {
        return reply.notFound('País não encontrado');
      }

      const states = await worldService.getStatesByCountry(countryId);
      return states;
    }
  );

  /**
   * GET /world/states/:stateId
   * Busca estado por ID
   */
  fastify.get<{ Params: { stateId: string } }>(
    '/states/:stateId',
    async (req, reply) => {
      const { stateId } = req.params;
      const state = await worldService.getStateById(stateId);

      if (!state) {
        return reply.notFound('Estado não encontrado');
      }

      return state;
    }
  );

  /**
   * GET /world/states/:stateId/cities
   * Lista cidades de um estado
   */
  fastify.get<{ Params: { stateId: string } }>(
    '/states/:stateId/cities',
    async (req, reply) => {
      const { stateId } = req.params;
      
      // Validar stateId
      const state = await worldService.getStateById(stateId);
      if (!state) {
        return reply.notFound('Estado não encontrado');
      }

      const cities = await worldService.getCitiesByState(stateId);
      return cities;
    }
  );

  /**
   * GET /world/cities/:cityId
   * Busca cidade por ID
   */
  fastify.get<{ Params: { cityId: string } }>(
    '/cities/:cityId',
    async (req, reply) => {
      const { cityId } = req.params;
      const city = await worldService.getCityById(cityId);

      if (!city) {
        return reply.notFound('Cidade não encontrada');
      }

      return city;
    }
  );

  /**
   * GET /world/cities/search?term=...
   * Busca cidades por termo
   */
  fastify.get<{
    Querystring: {
      term: string;
      countryId?: string;
      stateId?: string;
      limit?: number;
      offset?: number;
    };
  }>(
    '/cities/search',
    {
      schema: {
        querystring: {
          type: 'object',
          required: ['term'],
          properties: {
            term: { type: 'string' },
            countryId: { type: 'string' },
            stateId: { type: 'string' },
            limit: { type: 'number' },
            offset: { type: 'number' },
          },
        },
      },
    },
    async (req) => {
      const validated = searchCitiesQuerySchema.parse(req.query);
      const cities = await worldService.searchCities(validated.term, {
        countryId: validated.countryId,
        stateId: validated.stateId,
        limit: validated.limit,
        offset: validated.offset,
      });
      return cities;
    }
  );
};

export default worldRoutes;
















